"The first sync publishes about {0}, except those that may hold personal data, duplicate or replace a published document.": "Lần đồng bộ đầu tiên công bố khoảng {0}, trừ các tệp có thể chứa dữ liệu cá nhân, trùng lặp hoặc thay thế một tài liệu đã công bố.",
"Suggested for a source this large.": "Được đề xuất cho nguồn lớn như thế này.",
"Suggested for a source this small.": "Được đề xuất cho nguồn nhỏ như thế này.",
"These filters leave nothing to sync. Turn a file type back on or skip fewer folders.": "Bộ lọc này không còn gì để đồng bộ. Hãy bật lại một loại tệp hoặc bỏ qua ít thư mục hơn.",
"Connected. First sync started — documents become searchable as they’re read.": "Đã kết nối. Đã bắt đầu đồng bộ lần đầu — tài liệu tra cứu được ngay khi đọc xong.",
