"Home fills in as documents are published. You can still ask the assistant.": "Trang chủ sẽ dần có nội dung khi tài liệu được công bố. Bạn vẫn có thể hỏi trợ lý.",
"Ask anything": "Hỏi bất cứ điều gì",
"Answers come only from documents you can read in {0}, with their sources. Attach files or choose what to search; the suggestions are questions people in your role ask.": "Câu trả lời chỉ lấy từ các tài liệu bạn được xem trong {0}, luôn kèm nguồn. Bạn có thể đính kèm tệp hoặc chọn phạm vi tìm; các gợi ý là câu hỏi mà người cùng vai trò với bạn hay hỏi.",
"Chosen from your role’s questions, your spaces and what you read. The label on each card says why.": "Được chọn theo câu hỏi thường gặp của vai trò bạn, các cộng đồng bạn tham gia và những gì bạn đã đọc. Nhãn trên mỗi thẻ cho biết lý do.",
"Everything, by domain": "Mọi thứ, theo lĩnh vực",
"A domain opens Knowledge filtered to it; a topic goes straight to its documents.": "Chọn một lĩnh vực để mở mục Tài liệu đã lọc theo lĩnh vực đó; chọn một chủ đề để đến thẳng các tài liệu thuộc chủ đề.",
"Welcome to {0}": "Chào mừng bạn đến với {0}",
