"Start a conversation here, with files and a chosen scope. Your conversations are listed under Recent, lower in the sidebar.": "Bắt đầu cuộc trò chuyện ở đây, kèm tệp và phạm vi bạn chọn. Các cuộc trò chuyện của bạn nằm trong mục Gần đây, phía dưới thanh bên.",
"You’re all set. Ask your first question or open a document.": "Mọi thứ đã sẵn sàng. Hãy đặt câu hỏi đầu tiên hoặc mở một tài liệu.",
"By continuing with Google, you agree to the terms of service and privacy policy.": "Khi tiếp tục với Google, bạn đồng ý với điều khoản dịch vụ và chính sách quyền riêng tư.",
